INSERT INTO tarot_cards (id, name_ko, name_en, emoji, image_path, keywords, message) VALUES
  (0,  '바보',            'The Fool',          '🐾', '00.webp', ARRAY['시작', '자유', '설렘'],     $$새 모험이 시작되는 날이다냥~ 바보 카드는 두려움 없이 발을 내딛는 순수한 용기를 말하고 있다냥. 아직 지도는 없지만, 그래서 더 설레는 길이라냥. 완벽하지 않아도 괜찮으니 호기심이 이끄는 쪽으로 첫 발을 살포시 떼어보라냥. 계획보다 더 멋진 풍경이 기다리고 있을지도 모른다냥 🐾$$),
  (1,  '마법사',          'The Magician',      '✨', '01.webp', ARRAY['창조', '의지', '재능'],     $$네 안의 재능이 반짝이고 있다냥! 마법사는 필요한 도구가 이미 네 손에 쥐어져 있다는 신호라냥. 오늘은 평소에 미뤄두었던 일을 꺼내어 작은 첫걸음을 시작하기에 딱 좋은 기운이다냥. 집중한 만큼 결과가 따라오니, 손끝에 닿는 기회를 그냥 흘려보내지 말라냥 ✨$$),
  (2,  '여사제',          'The High Priestess','🌙', '02.webp', ARRAY['직관', '비밀', '고요'],     $$오늘은 마음의 소리에 귀 기울여야 하는 날이다냥. 여사제는 말보다 침묵, 논리보다 직감이 더 정확한 순간을 알려주고 있다냥. 급하게 결정하기보다 한 템포 늦춰서 스스로에게 물어보라냥 — 답은 이미 네 안에 조용히 앉아있다냥. 오늘 밤 꿈이나 우연히 스친 장면에서 힌트를 얻을지도 모른다냥 🌙$$),
  (3,  '여황제',          'The Empress',       '🌷', '03.webp', ARRAY['풍요', '사랑', '포근'],     $$포근한 사랑이 흘러넘치는 날이다냥~ 여황제는 돌봄과 풍요의 에너지를 가득 담고 왔다냥. 오늘은 좋아하는 음식, 좋아하는 향기, 좋아하는 사람에게 시간을 써도 괜찮다냥. 스스로에게도 다정해지라냥 — 네가 채워져야 남에게도 나눠줄 수 있다냥. 주변 사람에게 건네는 작은 친절이 오늘은 두 배로 돌아온다냥 🌷$$),
  (4,  '황제',            'The Emperor',       '👑', '04.webp', ARRAY['안정', '리더십', '체계'],   $$단단하게 중심을 잡으면 모든 게 제자리를 찾는 날이다냥. 황제는 흔들림 속에서도 원칙과 구조를 놓지 않는 사람을 지켜준다냥. 오늘은 우선순위를 적어보고, 해야 할 일과 미뤄도 되는 일을 냉정하게 나눠보라냥. 감정보다 논리가 앞서야 할 때이지만, 냉정함이 차가움이 되지 않게 주의하라냥 👑$$),
  (5,  '교황',            'The Hierophant',    '📚', '05.webp', ARRAY['배움', '전통', '조언'],     $$어른의 한마디가 큰 힘이 되는 날이다냥. 교황은 경험과 지혜, 그리고 오래된 가르침의 가치를 이야기하고 있다냥. 혼자 고민하지 말고 믿을 만한 선배나 멘토에게 조언을 청해보라냥 — 작은 힌트가 길을 바꿔줄지도 모른다냥. 오늘은 새로운 시도보다 검증된 방식이 더 든든한 결과를 가져다준다냥 📚$$),
  (6,  '연인',            'The Lovers',        '💕', '06.webp', ARRAY['인연', '선택', '조화'],     $$마음이 설레는 인연을 만날지도 모른다냥~ 연인 카드는 단순히 로맨스뿐 아니라 '진짜 원하는 것을 고르는 용기'를 뜻하기도 한다냥. 오늘은 두 갈래 길 중 하나를 골라야 하는 순간이 올 수도 있으니, 머리보다 가슴이 따뜻해지는 쪽으로 기울여보라냥. 함께 있을 때 자연스러운 사람, 그 사람이 답이다냥 💕$$),
  (7,  '전차',            'The Chariot',       '🚀', '07.webp', ARRAY['전진', '승리', '용기'],     $$망설이지 말고 달려보라냥! 전차는 방향이 정해졌다면 속도를 올려도 좋다는 초록불이다냥. 오늘은 네가 주인공이고, 고삐는 네 손에 있다냥. 주변 소음은 잠시 꺼두고 목표 한 가지에만 집중하라냥 — 오늘의 작은 돌파가 내일의 큰 성취를 만들어낸다냥. 포기하고 싶을 때가 바로 결승선 직전이다냥 🚀$$),
  (8,  '힘',              'Strength',          '🦁', '08.webp', ARRAY['용기', '인내', '다정'],     $$부드러움이 가장 강한 힘이다냥. 힘 카드는 사자를 힘으로 누르는 게 아니라 다정함으로 품어내는 장면을 담고 있다냥. 오늘 네 앞에 놓인 어려움도 정면 돌파보다 여유로운 미소로 대해보라냥. 스스로의 감정에도 엄격해지지 말고, 불안을 꼭 안아주라냥 — 천천히, 하지만 단단하게 나아가는 게 오늘의 승리 방식이다냥 🦁$$),
  (9,  '은둔자',          'The Hermit',        '🕯️', '09.webp', ARRAY['성찰', '지혜', '쉼'],       $$오늘은 혼자만의 시간이 보약이다냥~ 은둔자는 외부의 답이 아니라 내면의 등불을 켜라고 말하고 있다냥. SNS를 잠깐 덮어두고, 조용한 카페나 산책길에서 생각을 정리해보라냥. 쉬는 것도 훌륭한 성장이고, 멈춰서는 시간이 다음 걸음을 더 멀리 데려다준다냥. 오늘 얻은 통찰은 내일의 나침반이 될 것이다냥 🕯️$$),
  (10, '운명의 수레바퀴', 'Wheel of Fortune',  '🎡', '10.webp', ARRAY['변화', '기회', '흐름'],     $$흐름이 바뀌는 날이다냥! 운명의 수레바퀴는 정체된 상황에 새 바람이 불어온다는 신호다냥. 오늘 스쳐가는 우연한 만남이나 사소한 제안을 가볍게 넘기지 말라냥 — 그 안에 기회의 씨앗이 숨어 있을 수 있다냥. 모든 것은 돌고 돈다냥. 힘든 순간에는 곧 상승, 좋은 순간에는 겸손을 기억하라냥 🎡$$),
  (11, '정의',            'Justice',           '⚖️', '11.webp', ARRAY['균형', '공정', '선택'],     $$마음의 저울을 똑바로 두는 날이다냥. 정의 카드는 감정에 치우치지 않고, 사실과 진심을 정확히 마주보라고 말하고 있다냥. 오늘 내리는 결정이 꽤 오래 영향을 미칠 수 있으니 서두르지 말라냥. 스스로에게 솔직해지는 용기만 있으면, 결과는 너의 편이 되어줄 거다냥 ⚖️$$),
  (12, '매달린 사람',     'The Hanged Man',    '🙃', '12.webp', ARRAY['전환', '관점', '기다림'],   $$잠시 멈춰서 거꾸로 보라냥. 매달린 사람은 '지금 안 풀리는 것은 네가 틀려서가 아니라 각도가 다를 뿐'이라고 속삭이고 있다냥. 오늘은 밀어붙이기보다 한 발 물러서서 상황을 다시 관찰해보라냥. 기다림이 답답하게 느껴질 수 있지만, 곧 전혀 다른 출구가 보일 것이다냥. 희생처럼 느껴지는 그 시간이 사실은 가장 값진 준비 과정이다냥 🙃$$),
  (13, '죽음',            'Death',             '🦋', '13.webp', ARRAY['변화', '마무리', '재생'],   $$끝은 곧 새로운 시작이다냥~ 죽음 카드는 무서운 뜻이 아니라 '더 이상 맞지 않는 것과의 작별'을 뜻한다냥. 오늘은 오래 끌어오던 관계, 습관, 일 중에서 살짝 내려놓아도 괜찮은 게 있는지 살펴보라냥. 자리를 비워야 새로운 것이 들어오는 법이다냥. 가슴이 시원해지는 결단이 내일의 너를 훨씬 가볍게 만들어줄 거다냥 🦋$$),
  (14, '절제',            'Temperance',        '🍵', '14.webp', ARRAY['조화', '절제', '치유'],     $$급할수록 한 박자 쉬어가라냥. 절제 카드는 서로 다른 두 에너지를 섞어 가장 좋은 맛을 내는 연금술을 상징한다냥. 오늘은 일과 쉼, 사람과 혼자, 말과 침묵 사이의 비율을 잘 조절해보라냥. 극단으로 달리고 싶은 충동이 들더라도 중간에서 숨을 고르면 모든 게 천천히 치유된다냥. 고요함이 너의 가장 든든한 방패가 되어줄 거다냥 🍵$$),
  (15, '악마',            'The Devil',         '😈', '15.webp', ARRAY['유혹', '집착', '해방'],     $$마음을 묶고 있는 끈을 살짝 풀어보라냥~ 악마 카드는 네가 '어쩔 수 없다'고 믿고 있는 족쇄가 사실은 스스로 쥐고 있는 것이라고 알려주고 있다냥. 습관적인 걱정, 끊기 어려운 관계, 끝없는 자기 비난 중 오늘 하나만 내려놓아보라냥. 자유는 멀리 있지 않다냥 — 선택하는 순간 바로 네 것이 된다냥 😈$$),
  (16, '탑',              'The Tower',         '⚡', '16.webp', ARRAY['변동', '진실', '각성'],     $$흔들림은 새 길이 열리는 신호다냥. 탑 카드는 겉으로는 충격처럼 보여도 사실은 오래된 거짓이 무너지고 진실이 드러나는 순간을 의미한다냥. 오늘 예상치 못한 변화나 갈등이 찾아와도 당황하지 말라냥 — 낡은 구조가 사라져야 더 단단한 것이 그 자리에 설 수 있다냥. 뒤흔들린 자리에서 오히려 시야가 넓어지는 경험을 하게 될 거다냥 ⚡$$),
  (17, '별',              'The Star',          '🌟', '17.webp', ARRAY['희망', '치유', '영감'],     $$오늘은 마음을 열어두라냥 🌙 별 카드는 긴 어둠 뒤에 찾아오는 조용한 희망의 상징이다냥. 작은 빛이 너를 비추고 있으니, 스스로를 의심하지 말라냥. 오늘 떠오르는 영감, 우연히 보게 되는 장면, 누군가의 따뜻한 한마디가 네 영혼에 부드럽게 스며들 거다냥. 치유는 거창하지 않다냥 — 하늘을 올려다보는 그 잠깐만으로도 충분하다냥 🌟$$),
  (18, '달',              'The Moon',          '🌝', '18.webp', ARRAY['감성', '꿈', '직감'],       $$흐릿한 안개 너머에 답이 있다냥~ 달 카드는 논리로 잡히지 않는 세계, 꿈과 무의식과 직감의 영역을 가리킨다냥. 오늘은 누군가의 말이 진심인지 아닌지 유난히 예민하게 느껴질 수 있으니, 억지로 판단하지 말고 시간을 두고 지켜보라냥. 불안이 올라올 땐 종이에 마음을 적어보는 것도 좋다냥 — 써 내려가는 순간 안개가 걷힌다냥 🌝$$),
  (19, '태양',            'The Sun',           '☀️', '19.webp', ARRAY['행복', '성공', '활력'],     $$오늘은 햇살처럼 빛나는 하루다냥! 태양 카드는 타로에서 가장 순수하고 밝은 긍정의 상징이라냥. 숨겨왔던 재능이 인정받거나, 오래 준비한 일이 드디어 결실을 맺을 수도 있다냥. 자신감을 숨기지 말고 마음껏 웃고, 마음껏 자랑해도 괜찮다냥. 네가 빛날수록 주변도 함께 따뜻해지니, 오늘은 아낌없이 환하게 존재하라냥 ☀️$$),
  (20, '심판',            'Judgement',         '📯', '20.webp', ARRAY['부활', '결단', '용서'],     $$지난 일은 살포시 안아주라냥. 심판 카드는 과거의 경험을 정리하고 새 챕터로 건너가는 부활의 순간을 뜻한다냥. 오늘은 오래 마음에 남은 후회나 용서하지 못했던 기억을 한 번 꺼내어 천천히 바라봐도 괜찮다냥. 자책이 아닌 이해로 마무리할 때, 네 안에서 종소리가 울리며 새 챕터가 열린다냥. 너는 충분히 잘해왔다냥 📯$$),
  (21, '세계',            'The World',         '🌏', '21.webp', ARRAY['완성', '성취', '조화'],     $$한 바퀴가 아름답게 완성되는 날이다냥~ 세계 카드는 메이저 아르카나 여정의 마지막, 지금까지의 모든 배움이 하나로 연결되는 순간을 뜻한다냥. 오늘은 작지만 의미 있는 마무리가 기다리고 있을지도 모른다냥. 스스로를 듬뿍 칭찬하고, 다음 원을 그리기 전에 충분히 쉬어가라냥 — 완성의 기쁨을 서두르지 않고 천천히 맛보는 것이 오늘의 숙제다냥 🌏$$)
