-- tarot_cards 테이블 생성 (Phase 3 D-08)
-- 메이저 아르카나 22장. 운영 메타데이터(updated_at·is_active·sort_order) 미포함 (deferred).
-- amulet_types 패턴(create_amulet_types_table.sql) 참고.

CREATE TABLE IF NOT EXISTS tarot_cards (
  id INT PRIMARY KEY,
  name_ko TEXT NOT NULL,
  name_en TEXT NOT NULL,
  emoji TEXT NOT NULL,
  image_path TEXT NOT NULL,
  keywords TEXT[] NOT NULL,
  message TEXT NOT NULL
);

-- RLS 정책: anon role 읽기 가능 (Pitfall 3 빈 배열 반환 회피)
ALTER TABLE tarot_cards ENABLE ROW LEVEL SECURITY;

CREATE POLICY "tarot_cards_select_policy" ON tarot_cards
  FOR SELECT USING (true);

-- 22장 seed (boknyang-tarot/src/data/cards.ts의 메이저 아르카나 22장 메시지 그대로 추출, "~다냥" 톤 유지)
-- image_path는 D-11에 따라 단순 파일명만 저장 (클라이언트는 id 기반 정적 import 사용)
ON CONFLICT (id) DO NOTHING;
